Fixpoint ev_only (e : expr) : bool :=
  match e with
  | ELit _ | EVar _ => true
  | EAlu _ a b | EAluw _ a b | EMd _ a b | EMdw _ a b => (ev_only a && ev_only b)%bool
  | EExt _ _ _ a => ev_only a
  | EBlob _ _ _ _ => false
  end.

Lemma edenot_agree_ev : forall b E E' e, (forall n, (n < b)%nat -> ev E n = ev E' n) ->
